package com.aditya.day13.delivery; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/delivery") public class DeliveryController{final DeliveryRepo r;final DeliveryService s;DeliveryController(DeliveryRepo r,DeliveryService s){this.r=r;this.s=s;}@PostMapping("/partners")public DeliveryPartner create(@RequestBody DeliveryPartner p){return r.save(p);}@PostMapping("/partners/{id}/online")public DeliveryPartner online(@PathVariable UUID id){var p=r.findById(id).orElseThrow();p.setOnline(true);p.setAvailable(true);return r.save(p);}@PostMapping("/partners/{id}/location")public DeliveryPartner loc(@PathVariable UUID id,@RequestBody Map<String,Double>x){var p=r.findById(id).orElseThrow();p.setLat(x.getOrDefault("lat",0d));p.setLng(x.getOrDefault("lng",0d));return r.save(p);}@PostMapping("/nearest")public DeliveryPartner nearest(@RequestBody Map<String,Double>x){return s.nearest(x.get("lat"),x.get("lng"),r.findByOnlineTrueAndAvailableTrue());}}